@st.cache_resource(show_spinner="Loading BeeSafe AI model and reference chemistry…")
def load_model_bundle(model_path_string: str):
    # Only load locally generated, trusted joblib artifacts. Never load arbitrary uploads.
    path = Path(model_path_string)
    return joblib.load(path)

@st.cache_resource(show_spinner="Preparing the chemical reference space…")
def load_reference(npz_string: str, metadata_string: str):
    return load_reference_data(Path(npz_string), Path(metadata_string))

@st.cache_data(show_spinner=False)
def read_example_records(csv_string: str):
    path = Path(csv_string)
    if not path.is_file():
        return []
    try:
        df = pd.read_csv(path)
        required = {"name", "SMILES"}
        if not required.issubset(df.columns):
            return []
        names = [str(x) for x in df["name"].tolist()]
        smiles = [str(x) for x in df["SMILES"].tolist()]
        # Keep first valid examples; these are demos and may overlap the training data.
        result = []
        seen = set()
        for name, smi in zip(names, smiles):
            if name in seen or not smi.strip() or Chem.MolFromSmiles(smi) is None:
                continue
            seen.add(name)
            result.append({"name": name, "smiles": smi})
            if len(result) >= 6:
                break
        return result
    except Exception:
        return []


