@st.cache_data(show_spinner=False)
def mol_picture_png(canonical_smiles: str) -> bytes:
    """Draw the actual RDKit molecule, not a generative depiction."""
    mol = Chem.MolFromSmiles(canonical_smiles)
    if mol is None:
        raise ValueError("Cannot render an invalid molecular structure.")
    pic = Draw.MolToImage(mol, size=(760, 480))
    buffer = io.BytesIO()
    pic.save(buffer, format="PNG")
    return buffer.getvalue()


def count_descriptor_plot(descriptors: dict):
    """Only graph compatible integer-count descriptors together (no mixed units)."""
    fields = [
        ("H-bond acceptors", "NumHAcceptors"),
        ("H-bond donors", "NumHDonors"),
        ("Total rings", "RingCount"),
        ("Rotatable bonds", "NumRotatableBonds"),
        ("Aromatic rings", "NumAromaticRings"),
        ("Heavy atoms", "HeavyAtomCount"),
    ]
    data = pd.DataFrame([{"Feature": label, "Count": float(descriptors[key])}
                         for label, key in fields if key in descriptors])
    if data.empty:
        return None
    chart = alt.Chart(data).mark_bar(cornerRadiusEnd=5, color="#21877D").encode(
        y=alt.Y("Feature:N", sort=None, title=None, axis=alt.Axis(labelLimit=170)),
        x=alt.X("Count:Q", title="Count", scale=alt.Scale(zero=True)),
        tooltip=["Feature:N", alt.Tooltip("Count:Q", format=".0f")],
    ).properties(height=250).configure_title(color="#173E32", fontSize=17, anchor="start").configure_view(stroke=None).configure_axis(
        gridColor="#E5EAE2", labelColor="#314C3F", titleColor="#314C3F"
    )
    return chart


def local_shap_fingerprint_explanation(bundle, X):
    """Average local SHAP attribution across saved tree estimators.

    These attributions explain each base estimator's class-1 output before its
    per-fold probability calibration; they are not exact SHAP values for the
    final calibrated ensemble probability.
    """
    if str(bundle.get("feature_type", "morgan")).lower() != "morgan":
        raise ValueError("Local fingerprint SHAP is currently available only for Morgan-fingerprint models.")
    if not bundle.get("model_pairs"):
        raise ValueError("The saved bundle does not contain the Phase 08 ensemble members needed for this explanation.")
    import shap

    rows = []
    for pair in bundle["model_pairs"]:
        estimator = pair["estimator"]
        explainer = shap.TreeExplainer(estimator)
        values = explainer.shap_values(X, check_additivity=False)
        if isinstance(values, list):
            values = values[1] if len(values) > 1 else values[0]
        values = np.asarray(values)
        if values.ndim == 3:
            # Recent SHAP releases can return (samples, features, classes).
            values = values[:, :, 1] if values.shape[-1] > 1 else values[:, :, 0]
        if values.ndim != 2 or values.shape[0] != 1:
            raise ValueError(f"Unexpected SHAP output shape: {values.shape}")
        rows.append(values[0])
    mean_values = np.mean(np.vstack(rows), axis=0)
    table = pd.DataFrame({
        "Morgan bit": np.arange(len(mean_values)),
        "Mean base-model SHAP value": mean_values,
        "Absolute contribution": np.abs(mean_values),
        "Bit present in query": np.asarray(X[0]).astype(bool),
    })
    return table.sort_values("Absolute contribution", ascending=False).reset_index(drop=True)


